mapper.update:
UPDATE google_translation_monthly_usage
SET used_characters = used_characters + #{characters},
    provider_calls = provider_calls + 1,
    updated_at = #{now}
WHERE month_key = #{monthKey}
  AND used_characters + #{characters} <= #{characterLimit}
